import { readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = resolve(__dirname, '..');
const distDir = resolve(rootDir, 'dist');

// 1. Read dist/lib/index.d.ts generated by tsc
const libDtsPath = resolve(distDir, 'lib/index.d.ts');
const libDts = readFileSync(libDtsPath, 'utf8');

// 2. Build ESM dist/index.d.ts
const lines = libDts.split('\n');
const esmLines = [];

for (const line of lines) {
  // Strip CSS import and sourcemap comments
  if (line.includes('index.css') || line.includes('sourceMappingURL')) continue;

  // Remap relative path from ../components to ./components and add .js for ESM Node16/NodeNext
  let updated = line
    .replace('from "../components/ui/', 'from "./components/ui/')
    .replace('from "./utils"', 'from "./lib/utils.js"');

  if (updated.includes('from "./components/ui/')) {
    updated = updated.replace(/(";|" };)/, (m) => (m === '";' ? '.js";' : '.js" };'));
  }

  esmLines.push(updated);
}

const esmContent = esmLines.join('\n');
writeFileSync(resolve(distDir, 'index.d.ts'), esmContent, 'utf8');

// 3. Build CommonJS dist/index.d.cts
// Re-exports from the ESM declaration with CJS module semantics
writeFileSync(
  resolve(distDir, 'index.d.cts'),
  'export * from "./index.js";\n',
  'utf8'
);

// 4. Build Stylesheet Typings
const cssDtsContent = 'declare const styles: string;\nexport default styles;\n';
const cssDctsContent = 'declare const styles: string;\nexport = styles;\n';

writeFileSync(resolve(distDir, 'styles.css.d.ts'), cssDtsContent, 'utf8');
writeFileSync(resolve(distDir, 'styles.css.d.cts'), cssDctsContent, 'utf8');

// Also create root styles.css and styles.css.d.ts for legacy Node10 resolution
writeFileSync(
  resolve(rootDir, 'styles.css'),
  '@import "./dist/styles.css";\n',
  'utf8'
);
writeFileSync(resolve(rootDir, 'styles.css.d.ts'), cssDtsContent, 'utf8');

// 5. Sanitize React imports for Next.js / Webpack compatibility
// Rolldown / Vite constant-folds Radix UI's dynamic useEffectEvent lookup into e.useEffectEvent.
// In Webpack (used by Next.js), accessing e.useEffectEvent on namespace import 'react' causes Webpack
// to generate a static named import 'import { useEffectEvent } from "react"', which fails at build time.
for (const jsFile of ['dist/index.js', 'dist/index.cjs']) {
  const filePath = resolve(rootDir, jsFile);
  let js = readFileSync(filePath, 'utf8');
  if (js.includes('.useEffectEvent')) {
    js = js.replace(/\.useEffectEvent\b/g, '["use" + "EffectEvent"]');
    writeFileSync(filePath, js, 'utf8');
  }
}

console.log('✅ Generated clean ESM & CJS TypeScript declarations and sanitized Webpack/Next.js runtime bundles');
